"use client";

import React, { useState, useEffect, useRef } from "react";
import { useRouter } from "next/router";

export default function AptitudeTest() {
  const router = useRouter();

  const [step, setStep] = useState("loading");
  const [timer, setTimer] = useState(20 * 60);
  const [questions, setQuestions] = useState([]);
  const [answers, setAnswers] = useState({});
  const [tabCount, setTabCount] = useState(0);
  const [autoSubmitReason, setAutoSubmitReason] = useState("");

  const submittedRef = useRef(false);

  const BACKEND_URL = "https://your-backend-domain.com"; // 🔴 CHANGE THIS

  /* ---------------- FETCH QUESTIONS FROM JAVA BACKEND ---------------- */
  useEffect(() => {
    if (router.query.start === "true") {
     fetch("https://your-java-backend.com/api/v1/questions?category=aptitude")
        .then(res => res.json())
        .then(data => {
          if (!Array.isArray(data) || data.length === 0) {
            alert("No aptitude questions found.");
            router.push("/");
            return;
          }
          setQuestions(data);
          setStep("test");
        })
        .catch(() => {
          alert("Server error while loading questions.");
          router.push("/");
        });
    }
  }, [router.query.start]);

  /* ---------------- TIMER ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const interval = setInterval(() => {
      setTimer(prev => {
        if (prev <= 1) {
          triggerAutoSubmit("Time ended. Test auto-submitted.");
          clearInterval(interval);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [step]);

  /* ---------------- SECURITY ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const block = e => e.preventDefault();
    const blockKeys = e => {
      if (
        e.key === "F12" ||
        (e.ctrlKey && e.shiftKey && ["I", "J", "C"].includes(e.key)) ||
        (e.ctrlKey && e.key === "U")
      ) {
        triggerAutoSubmit("Rule violation detected.");
      }
    };

    document.addEventListener("contextmenu", block);
    document.addEventListener("copy", block);
    document.addEventListener("cut", block);
    document.addEventListener("paste", block);
    document.addEventListener("keydown", blockKeys);

    return () => {
      document.removeEventListener("contextmenu", block);
      document.removeEventListener("copy", block);
      document.removeEventListener("cut", block);
      document.removeEventListener("paste", block);
      document.removeEventListener("keydown", blockKeys);
    };
  }, [step]);

  /* ---------------- TAB SWITCH DETECTION ---------------- */
  useEffect(() => {
    if (step !== "test") return;

    const handleVisibility = () => {
      if (document.visibilityState === "hidden") {
        setTabCount(prev => {
          const count = prev + 1;
          if (count <= 2) alert(`Warning ${count}/3: Tab switching not allowed.`);
          if (count >= 3) triggerAutoSubmit("Multiple tab switches detected.");
          return count;
        });
      }
    };

    document.addEventListener("visibilitychange", handleVisibility);
    return () => document.removeEventListener("visibilitychange", handleVisibility);
  }, [step]);

  /* ---------------- AUTO SUBMIT ---------------- */
  const triggerAutoSubmit = message => {
    if (submittedRef.current) return;
    submittedRef.current = true;
    setAutoSubmitReason(message);
    submitTest(true);
  };

  /* ---------------- SUBMIT TEST TO JAVA BACKEND ---------------- */
  const submitTest = async (forced = false) => {
    const studentId = localStorage.getItem("studentId");

    if (!studentId) {
      alert("Session expired. Please register again.");
      router.push("/");
      return;
    }

    if (!forced && Object.keys(answers).length < questions.length) {
      alert("Answer all questions.");
      return;
    }

    try {
      await fetch(`${BACKEND_URL}/api/v1/tests`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          studentId,
          category: "aptitude",
          answers
        }),
      });
    } catch (err) {
      console.error("Submit error:", err);
    }

    setStep("submitted");
  };

  const minutes = String(Math.floor(timer / 60)).padStart(2, "0");
  const seconds = String(timer % 60).padStart(2, "0");

  /* ---------------- SUBMITTED SCREEN ---------------- */
  if (step === "submitted") {
    return (
      <CenteredCard title="Aptitude Test Submitted">
        <p className="text-red-600 text-center mb-4 font-semibold">
          {autoSubmitReason || "Your test has been submitted successfully."}
        </p>
        <button onClick={() => router.push("/")} className="w-full bg-blue-600 text-white py-2 rounded">
          OK
        </button>
      </CenteredCard>
    );
  }

  if (step === "loading") {
    return (
      <CenteredCard title="Loading Questions...">
        <p className="text-center">Please wait...</p>
      </CenteredCard>
    );
  }

  /* ---------------- TEST UI ---------------- */
  return (
    <div className="min-h-screen bg-gray-100 px-3 py-4 select-none">
      <div className="sticky top-0 bg-white shadow rounded-xl px-4 py-3 flex justify-between">
        <h2 className="font-bold">Aptitude Test</h2>
        <span className="text-red-600 font-bold">⏱ {minutes}:{seconds}</span>
      </div>

      <div className="max-w-3xl mx-auto mt-4">
        {questions.map((q, i) => (
          <div key={q.id} className="bg-white p-4 rounded-xl shadow mb-4">
            <p className="font-semibold mb-3">{i + 1}. {q.question}</p>

            {[q.option_a, q.option_b, q.option_c, q.option_d].map(opt => (
              <button
                key={opt}
                onClick={() => setAnswers(p => ({ ...p, [q.id]: opt }))}
                className={`w-full px-4 py-2 mb-2 border rounded ${
                  answers[q.id] === opt ? "bg-blue-600 text-white" : "bg-white"
                }`}
              >
                {opt}
              </button>
            ))}
          </div>
        ))}

        <button onClick={() => submitTest()} className="w-full bg-green-600 text-white py-3 rounded-xl font-bold">
          Submit Test
        </button>
      </div>
    </div>
  );
}

const CenteredCard = ({ title, children }) => (
  <div className="min-h-screen flex items-center justify-center bg-gray-100 px-3">
    <div className="bg-white p-6 rounded-xl shadow w-full max-w-lg text-center">
      <h2 className="text-xl font-bold mb-4">{title}</h2>
      {children}
    </div>
  </div>
);